namespace UserAccess.Api.Tests;

public sealed class PasswordHasherTests
{
    [Fact]
    public void HashPassword_ProducesDifferentHashEachTime()
    {
        var password = "P@ssw0rd!";

        var hash1 = PasswordHasher.HashPassword(password);
        var hash2 = PasswordHasher.HashPassword(password);

        Assert.NotEqual(hash1, hash2);
        Assert.True(PasswordHasher.VerifyPassword(password, hash1));
        Assert.True(PasswordHasher.VerifyPassword(password, hash2));
    }

    [Fact]
    public void VerifyPassword_ReturnsFalseForWrongPassword()
    {
        var hash = PasswordHasher.HashPassword("P@ssw0rd!");

        Assert.False(PasswordHasher.VerifyPassword("WrongPassword!", hash));
    }
}

using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using UserAccess.Api.Domain.Entities;

namespace UserAccess.Api.Infrastructure.Persistence;

internal sealed class UserConfiguration : IEntityTypeConfiguration<User>
{
    public void Configure(EntityTypeBuilder<User> builder)
    {
        builder.ToTable("Users", table => table.HasCheckConstraint(
            "CK_Users_Email_Format",
            "length(\"Email\") BETWEEN 6 AND 254 " +
            "AND instr(\"Email\", '@') > 1 " +
            "AND length(\"Email\") - length(replace(\"Email\", '@', '')) = 1 " +
            "AND instr(substr(\"Email\", instr(\"Email\", '@') + 1), '.') > 1 " +
            "AND instr(\"Email\", ' ') = 0 " +
            "AND instr(\"Email\", '..') = 0 " +
            "AND \"Email\" = trim(\"Email\")"));

        builder.HasKey(user => user.Id);

        builder.Property(user => user.FirstName)
            .HasMaxLength(100)
            .IsRequired();

        builder.Property(user => user.LastName)
            .HasMaxLength(100)
            .IsRequired();

        builder.Property(user => user.Email)
            .HasMaxLength(254)
            .UseCollation("NOCASE")
            .IsRequired();

        builder.HasIndex(user => user.Email)
            .IsUnique()
            .HasDatabaseName("UX_Users_Email");

        builder.Property(user => user.PasswordHash)
            .HasMaxLength(512)
            .IsRequired();

        builder.Property(user => user.ImagePath)
            .HasMaxLength(2048);

        builder.Property(user => user.CreatedAtUtc)
            .IsRequired();
    }
}

using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
