namespace UserAccess.Api.Controllers;

[ApiController]
[Route("api/auth")]
public sealed class AuthController : ControllerBase
{
    private readonly UserDbContext _dbContext;
    private readonly JwtSettings _jwtSettings;

    public AuthController(UserDbContext dbContext, IOptions<JwtSettings> jwtSettings)
    {
        _dbContext = dbContext;
        _jwtSettings = jwtSettings.Value;
    }

    [HttpPost("token")]
    [ProducesResponseType(typeof(ApiResponse<AuthTokenResponse>), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ValidationProblemDetails), StatusCodes.Status400BadRequest)]
    [ProducesResponseType(typeof(ErrorResponse), StatusCodes.Status401Unauthorized)]
    public async Task<ActionResult<ApiResponse<AuthTokenResponse>>> PostToken([FromBody] CreateTokenRequest request, CancellationToken cancellationToken)
    {
        if (!ModelState.IsValid)
        {
            return ValidationProblem(ModelState);
        }

        var normalizedEmail = request.Email.Trim();
        var user = await _dbContext.Users
            .AsNoTracking()
            .SingleOrDefaultAsync(x => x.Email == normalizedEmail, cancellationToken);

        if (user is null || !PasswordHasher.VerifyPassword(request.Password, user.PasswordHash))
        {
            return Unauthorized(new ErrorResponse("Invalid email or password.", StatusCodes.Status401Unauthorized, HttpContext.TraceIdentifier));
        }

        var expiresAtUtc = DateTimeOffset.UtcNow.AddMinutes(_jwtSettings.ExpiryMinutes);
        var token = CreateToken(user, expiresAtUtc);

        var response = new AuthTokenResponse(token, expiresAtUtc, "Bearer");
        return Ok(ApiResponse<AuthTokenResponse>.Ok(response, "Authentication successful."));
    }

    private string CreateToken(User user, DateTimeOffset expiresAtUtc)
    {
        var key = string.IsNullOrWhiteSpace(_jwtSettings.Key)
            ? "demo-local-development-signing-key-for-interview"
            : _jwtSettings.Key;

        var signingKeyBytes = Encoding.UTF8.GetBytes(key);
        var keyMaterial = signingKeyBytes.Length >= 32
            ? signingKeyBytes
            : SHA256.HashData(signingKeyBytes);

        var signingKey = new SymmetricSecurityKey(keyMaterial);
        var credentials = new SigningCredentials(signingKey, SecurityAlgorithms.HmacSha256);

        var claims = new[]
        {
            new Claim(JwtRegisteredClaimNames.Sub, user.Id.ToString()),
            new Claim(JwtRegisteredClaimNames.Email, user.Email),
            new Claim(ClaimTypes.NameIdentifier, user.Id.ToString()),
            new Claim(ClaimTypes.Email, user.Email),
            new Claim(ClaimTypes.Name, user.FirstName + " " + user.LastName)
        };

        var token = new JwtSecurityToken(
            issuer: _jwtSettings.Issuer,
            audience: _jwtSettings.Audience,
            claims: claims,
            notBefore: DateTime.UtcNow,
            expires: expiresAtUtc.UtcDateTime,
            signingCredentials: credentials);

        return new JwtSecurityTokenHandler().WriteToken(token);
    }
}

